      // re-engaged shape on the glass.
      await harness.waitForOutput(settleMs: 400);
      final settledLive = harness.screenText;
      expect(
        settledLive,
        isNot(contains(RegExp(r'● \d+ new'))),
        reason: 'the counter resets when the unseen tail is revealed',
