        // sleep holds the run open for the End press, and a final text
        // segment settles it.
        ..enqueueToolCall('bash', '{"command": "sleep 1"}')
        ..enqueueToolCall('bash', '{"command": "sleep 1"}')
        ..enqueueToolCall('bash', '{"command": "sleep 1"}')
        ..enqueueToolCall('bash', '{"command": "sleep 1"}')
        ..enqueueToolCall('bash', '{"command": "sleep 1"}')
        ..enqueueToolCall('bash', '{"command": "sleep 8"}')
