bool _isRuleRow(String row) =>
    row.isNotEmpty && row.runes.every((r) => r == 0x2500);

int _ruleRowCount(List<String> rows) => rows.where(_isRuleRow).length;

/// Whether [rows] carries the textless fold rule: one MORE pure rule row
