    final labelCell = tuiPadRight(
      tuiFitWidth(label, _busyLabelCells),
      _busyLabelCells,
    );
    final elapsedCell = _formatBusyElapsed(
      elapsedSeconds,
    ).padLeft(_busyElapsedCells);
    final plain = '$labelCell $elapsedCell${suffix.isEmpty ? '' : ' $suffix'}';
