  onModelSelected: (_) async {},
  buildSlashMenu: (_) => const [],
  buildModelMenu: (_, _) => const [],
  statusLine: () => '/work · 0tok · turn 0 · test-model',
  prompt: 'fa> ',
);

FaTuiModel _build({int termWidth = 100, int termHeight = 24}) => FaTuiModel(
  callbacks: _callbacks(),
  isExited: () => false,
  termWidth: termWidth,
  termHeight: termHeight,
);

FaTuiModel _send(FaTuiModel m, Msg msg) => m.update(msg).$1 as FaTuiModel;

String _screen(FaTuiModel m) => _rowsOf(m).where((r) => r.trim().isNotEmpty).join('\n');

List<String> _rowsOf(FaTuiModel m) =>
    m.view().content.split('\n').map((r) => stripAnsi(r)).toList();

final _anchor = RegExp(r'^─+\n.{0,4}Background jobs \(\d+\)', multiLine: true);

const _board = ['◐ Background jobs (5)', 'sh-1 sleep 1'];

void main() {
  test('HELD (detached, busy, counted) does NOT match the pair anchor', () {
    var m = _build().copyWith(
      outputLines: [for (var i = 1; i <= 30; i++) 'seed line $i'],
      jobBoardLines: _board,
    );
    m = _send(m, const BusyMsg(true));
    m = _send(m, const OutputMsg('seed', newline: true)); // latch bottom
    m = _send(m, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    for (var i = 0; i < 3; i++) {
      m = _send(m, OutputMsg('late $i', newline: true));
    }
    expect(m.followTail, isFalse);
    expect(m.follow.unseen, 3);
    final screen = _screen(m);
    print('--- HELD screen ---\n$screen');
    expect(screen, contains('● 3 new'), reason: 'held rule carries text');
    expect(
      _anchor.hasMatch(screen),
      isFalse,
      reason: 'held rule row carries percent/counter text — '
          '^─+\\n can never match it',
    );
  });

  test('LIVE (following, busy, board) matches the pair anchor', () {
    var m = _build().copyWith(
      outputLines: [for (var i = 1; i <= 30; i++) 'seed line $i'],
      jobBoardLines: _board,
    );
    m = _send(m, const BusyMsg(true));
    m = _send(m, const OutputMsg('seed', newline: true));
    m = _send(m, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    for (var i = 0; i < 3; i++) {
      m = _send(m, OutputMsg('late $i', newline: true));
    }
    m = _send(m, KeyPressMsg(const TeaKey(code: KeyCode.end)));
    expect(m.followTail, isTrue);
    final screen = _screen(m);
    print('--- LIVE screen ---\n$screen');
    expect(
      _anchor.hasMatch(screen),
      isTrue,
      reason: 'textless fold rule sits directly above the board summary',
    );
  });

  test('LIVE with icon clipped away (clip ladder) still matches', () {
    // Narrow width: the icon clips first, the line starts at
    // 'Background jobs (N)' — .{0,4} must cover zero chars.
    var m = _build(termWidth: 40).copyWith(
      outputLines: [for (var i = 1; i <= 30; i++) 'seed line $i'],
      jobBoardLines: ['◐ Background jobs (5)'],
    );
    m = _send(m, const BusyMsg(true));
    m = _send(m, const OutputMsg('seed', newline: true));
    final screen = _screen(m);
    print('--- LIVE narrow screen ---\n$screen');
    expect(_anchor.hasMatch(screen), isTrue);
  });
}
